// Original imagegen brick material, downsampled to 256px. No external asset requests.
import * as THREE from 'three';
import { fbm, hash } from '../engine/look.js';
const BRICK='data:image/jpeg;base64,';

// Counter the warm sun on masonry only; preserve mortar and image grain.
function brownMasonry(ctx,w,h,facade=false){
 const im=ctx.getImageData(0,0,w,h),d=im.data;
 for(let i=0;i<d.length;i+=4){
  const r=d[i],g=d[i+1],b=d[i+2];
  if(facade && !(r>g*1.12 && r>b*1.18))continue;
  d[i]=r*.92;d[i+1]=g*1.06+6;d[i+2]=b*1.22+14;
 }ctx.putImageData(im,0,0);
}

let canvas;
const textures=[];
export function uvaBrick(rx=1,ry=1){
  if(!canvas){
    canvas=document.createElement('canvas');canvas.width=canvas.height=256;
    const ctx=canvas.getContext('2d');ctx.fillStyle='#945d45';ctx.fillRect(0,0,256,256);
    const image=new Image();
    image.onload=()=>{ctx.drawImage(image,0,0,256,256);brownMasonry(ctx,256,256);for(const t of textures)t.needsUpdate=true;};
    image.src=BRICK;
  }
  const t=new THREE.CanvasTexture(canvas);
  t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(rx,ry);
  t.magFilter=THREE.LinearFilter;t.minFilter=THREE.LinearMipmapLinearFilter;
  textures.push(t);return t;
}

// Round two: original imagegen facade/material atlas, JPEG 512px q78.
const UVA_TILES = {
pavilion: 'data:image/jpeg;base64,',
room: 'data:image/jpeg;base64,',
drum: 'data:image/jpeg;base64,',
cabell: 'data:image/jpeg;base64,',
grass: 'data:image/jpeg;base64,',
path: 'data:image/jpeg;base64,',
stone: 'data:image/jpeg;base64,',
roof: 'data:image/jpeg;base64,',
leaves: 'data:image/jpeg;base64,',
};
const tileCache = new Map();
export function uvaTexture(name, rx=1, ry=1) {
 const key = `${name}:${rx}:${ry}`; if(tileCache.has(key))return tileCache.get(key);
 const t=new THREE.TextureLoader().load(UVA_TILES[name],loaded=>{
  if(!['path','room','drum','cabell','pavilion'].includes(name))return;
  const c=document.createElement('canvas');c.width=loaded.image.width;c.height=loaded.image.height;
  const g=c.getContext('2d');g.drawImage(loaded.image,0,0);brownMasonry(g,c.width,c.height,name!=='path');
  loaded.image=c;loaded.needsUpdate=true;
 });t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(rx,ry);t.magFilter=THREE.LinearFilter;t.minFilter=THREE.LinearMipmapLinearFilter;tileCache.set(key,t);return t;
}

/* Image generation provenance (built-in imagegen, round two):
Original production UVA Lawn 2003-console-game atlas: flat front-on photographic
surfaces, soft dirty detail, neutral warm light; no people, sky, labels or game assets.
3x3 tiles: two-story Jeffersonian pavilion with sash windows and shutters;
one-story student room with paneled door and fanlight; two-level Rotunda drum bay;
Old Cabell arched facade; seamless olive grass; herringbone brick paving;
weathered off-white marble/stucco; standing-seam roof; autumn leaves on grass.
Nine tiles cropped to 512px JPEG quality 78, embedded above. Original brick retained.
*/

// Round three: small repeatable construction materials, authored in canvas.
// UV units are metres: a ceiling tile spans 1.2m, with six painted boards.
const detailCache = new Map();
export function uvaDetail(name) {
 if (detailCache.has(name)) return detailCache.get(name);
 const c=document.createElement('canvas');c.width=c.height=256;const g=c.getContext('2d');
 const bases={grass:'#7e934a',boards:'#c4bda9',coffers:'#d3c8ad',stone:'#e4d8bd',trim:'#c9c5b8',tread:'#b0a896',wood:'#765039',iron:'#393b39',bag:'#59634b',book:'#8c4639',roof:'#777877'};
 g.fillStyle=bases[name]||'#c9bda0';g.fillRect(0,0,256,256);
 // Broad mineral stains, medium weathering and fine grain survive minification.
 const base=g.getImageData(0,0,1,1).data, img=g.createImageData(256,256);
 for(let y=0;y<256;y++)for(let x=0;x<256;x++){
  const broad=fbm(x/256,y/256,6,6,31),medium=fbm(x/256,y/256,28,28,14),grain=hash(x,y,9);
  const n=name==='grass' ? (broad-.5)*150+(medium-.5)*85+(grain-.5)*24 : name==='trim' ? (broad-.5)*18+(medium-.5)*12+(grain-.5)*6 : name==='stone' ? (broad-.5)*55+(medium-.5)*40+(grain-.5)*23 : (broad-.5)*74+(medium-.5)*32+(grain-.5)*18;
  const k=(y*256+x)*4;
  for(let c=0;c<3;c++)img.data[k+c]=base[c]+n;
  img.data[k+3]=255;
 }
 g.putImageData(img,0,0);
 if(name==='notice'){
  g.fillStyle='#30362e';g.fillRect(0,0,256,256);
  g.fillStyle='#eee0bb';g.font='bold 25px Georgia';g.textAlign='center';
  g.fillText('LAWN MUSIC',128,115);g.font='18px Georgia';g.fillText('FRIDAY',128,151);
  for(let i=0;i<200;i++){g.fillStyle='rgba(194,181,151,.22)';g.fillRect(hash(i,1,77)*256,hash(i,2,77)*256,3,2);}
 }
 if(name==='fallenLeaves'){
  g.fillStyle='#687343';g.fillRect(0,0,256,256);
  for(let i=0;i<650;i++){
   const x=hash(i,1,87)*256,y=hash(i,2,87)*256;
   g.save();g.translate(x,y);g.rotate(hash(i,3,87)*6.28);
   g.fillStyle=['#8b763c','#a48549','#6b633a','#bc9959'][i%4];
   g.beginPath();g.ellipse(0,0,2+hash(i,4,87)*2,1.4,0,0,6.28);g.fill();g.restore();
  }
 }
 if(name==='ridge'){
  g.fillStyle='#a3a8ca';g.fillRect(0,0,256,256);
  for(let i=0;i<18;i++){
   const x=i*16-8,h=10+hash(i,2,60)*20,y=2+hash(i,3,60)*24;
   g.fillStyle=i%2?'#8294b4':'#95a0be';g.fillRect(x,y,13,h);
   g.fillStyle='#7d8aa7';g.beginPath();g.moveTo(x-2,y);g.lineTo(x+6,y-6);g.lineTo(x+15,y);g.fill();
   g.fillStyle='#a9b0cb';for(let k=0;k<3;k++)g.fillRect(x+2+k*4,y+5,2,4);
  }
  for(let i=0;i<140;i++){
   g.fillStyle=i%2?'rgba(100,125,150,.12)':'rgba(194,188,206,.12)';
   g.fillRect(hash(i,5,60)*256,hash(i,6,60)*256,14+hash(i,7,60)*30,2);
  }
 }
 if(name==='blanket'){
  // Soft woven checks, larger than the previous shimmering gingham.
  for(let y=0;y<256;y++)for(let x=0;x<256;x++){
   const wave=Math.tanh(3*Math.sin(x*Math.PI/24))*Math.tanh(3*Math.sin(y*Math.PI/24));
   const grain=(hash(x,y,92)-.5)*8,fold=5*Math.sin(y*.055+x*.014);
   const k=(y*256+x)*4;
   [195,167,210].forEach((v,c)=>img.data[k+c]=v+wave*[28,76,90][c]+grain+fold);
  }g.putImageData(img,0,0);
 }
 if(name==='grass'){
  for(let i=0;i<18000;i++){
   const x=hash(i,1,3)*256,y=hash(i,2,3)*256;
   g.strokeStyle=i%3?'rgba(45,77,29,.24)':'rgba(208,194,99,.38)';g.lineWidth=.65;
   g.beginPath();g.moveTo(x,y);g.lineTo(x+hash(i,4,3)*3-1,y-2-hash(i,5,3)*3);g.stroke();
  }
 }
 if(name==='boards'||name==='wood'){
  for(let x=0;x<256;x+=32){g.fillStyle='#766e60';g.fillRect(x,0,2,256);g.fillStyle='#ddd3b9';g.fillRect(x+2,0,1,256);
   g.fillStyle='#807564';g.fillRect(x,(x*3)%224,32,2);
   for(let y=12;y<256;y+=64){g.fillStyle='#786f62';g.fillRect(x+5,y,2,2);}}
 } else if(name==='coffers'){
  for(let row=0;row<2;row++)for(let col=0;col<2;col++){
   const x=col*128,y=row*128;
   g.fillStyle='#766f62';g.fillRect(x+4,y+4,120,120);
   g.fillStyle='#d4cbb9';g.fillRect(x+8,y+8,112,112);
   g.fillStyle='#928d81';g.fillRect(x+15,y+15,98,98);
   g.fillStyle=['#c7bfab','#b1b4aa','#bcb29b','#c6c3b5'][row*2+col];g.fillRect(x+19,y+21,90,88);
  }
 } else if(name==='roof'){
  for(let x=0;x<256;x+=64){g.fillStyle='#65635b';g.fillRect(x,0,2,256);g.fillStyle='#d0c6af';g.fillRect(x+2,0,1,256);}
  for(let y=0;y<256;y+=128){g.fillStyle='#79766c';g.fillRect(0,y,256,2);}
 } else if(name==='tread'){
  g.fillStyle='rgba(55,58,56,.55)';g.fillRect(0,0,3,256);
  g.fillStyle='rgba(238,233,214,.55)';g.fillRect(3,0,2,256);
  for(let i=0;i<70;i++){
   const x=hash(i,7,81)*256,y=hash(i,8,81)*256;
   g.fillStyle=i%3?'rgba(57,61,53,.25)':'rgba(239,230,204,.4)';
   g.fillRect(x,y,1+hash(i,9,81)*12,1+hash(i,10,81)*3);
  }
  for(let i=0;i<7;i++){
   const x=hash(i,11,81)*256,y=hash(i,12,81)*256,r=15+hash(i,13,81)*35;
   const a=g.createRadialGradient(x,y,0,x,y,r);a.addColorStop(0,'rgba(45,55,48,.4)');a.addColorStop(1,'rgba(45,55,48,0)');g.fillStyle=a;g.fillRect(x-r,y-r,r*2,r*2);
  }

  // Irregular polished foot wear, with pits, rather than a ruled paving grid.
  for(let i=0;i<35;i++){const x=hash(i,1,71)*256,y=hash(i,2,71)*256,r=9+hash(i,3,71)*27;
   const a=g.createRadialGradient(x,y,0,x,y,r);a.addColorStop(0,'rgba(236,224,195,.26)');a.addColorStop(1,'rgba(236,224,195,0)');g.fillStyle=a;g.fillRect(x-r,y-r,2*r,2*r);}
 } else if(name==='bag'||name==='book'){
  g.strokeStyle='#d0b88a';g.lineWidth=2;g.strokeRect(12,12,232,232);g.strokeRect(48,125,160,100);
  g.fillStyle='#292d28';g.fillRect(32,20,15,220);g.fillRect(210,20,15,220);
  g.fillStyle='#a99768';g.fillRect(90,48,76,34);
 }
 if(name==='coffers'||name==='boards'||name==='trim'){
  for(let i=0;i<95;i++){const x=hash(i,1,91)*256,y=hash(i,2,91)*256,r=4+hash(i,3,91)*24;
   const a=g.createRadialGradient(x,y,0,x,y,r);a.addColorStop(0,'rgba(76,64,44,.15)');a.addColorStop(1,'rgba(76,64,44,0)');g.fillStyle=a;g.fillRect(x-r,y-r,r*2,r*2);}
 }
 const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.magFilter=THREE.LinearFilter;t.minFilter=THREE.LinearMipmapLinearFilter;
 detailCache.set(name,t);return t;
}
